def validate_items(items):
    if not items or any(quantity < 0 for quantity in [item['quantity'] for item in items]):
        raise ValueError("Invalid items: list cannot be empty and quantities must be non-negative.")

def calculate_subtotal(items):
    return sum(item['price'] * item['quantity'] for item in items)

def apply_discount(subtotal, vip_status):
    if vip_status:
        return subtotal * 0.9
    return subtotal

def calculate_tax(subtotal, tax_rate):
    return subtotal * tax_rate

def format_receipt(items, total, tax_amount):
    return f"Receipt\nItems:\n{''.join([f'{item["name"]} x{item["quantity"]} = ${item["price"]*item["quantity"]}' for item in items])}\nSubtotal: ${subtotal:.2f}\nTax (${tax_rate*100}%): ${tax_amount:.2f}\nTotal: ${total:.2f}"

def process_order(items, vip_status, tax_rate):
    validate_items(items)
    subtotal = calculate_subtotal(items)
    total = apply_discount(subtotal, vip_status)
    tax_amount = calculate_tax(subtotal, tax_rate)
    return format_receipt(items, total, tax_amount)
